#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <stdbool.h>
#include <inttypes.h>

static long compute_gcd(long a, long b)
{
    while (b != 0) {
        long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

static bool mul_overflow(long a, long b, long *out)
{
    __int128 prod = (__int128)a * (__int128)b;
    if (prod > LLONG_MAX || prod < LLONG_MIN)
        return true;
    *out = (long)prod;
    return false;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    long abs_a = (a < 0) ? -a : a;
    long abs_b = (b < 0) ? -b : b;

    if (abs_a > 1000000L || abs_b > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    long gcd = compute_gcd(abs_a, abs_b);
    long div = abs_a / gcd;
    long lcm;
    if (mul_overflow(div, abs_b, &lcm)) {
        puts("OVERFLOW");
        return 0;
    }

    printf("gcd=%ld lcm=%ld\n", gcd, lcm);
    return 0;
}
